      "Beutelgallerten sind olivgrüne Schlicke ähnlich wie die im Monsterhandbuch beschriebenen Kerker-Aasjäger. Wie der Name schon sagt, sind diese Kreaturen meist in Beuteln von Riesen anzutreffen, wo sie jedes organische Material verschlingen, das sie finden. Beutelgallerten sind dagegen resistent, gequetscht zu werden, sodass sie es überleben, wenn der Riese seinen Beutel wirft, sich draufsetzt oder ihn als provisorische Keule verwendet.",
      "Manche Riesen halten ihre Beutel peinlichst sauber, um keine Beutelgallerten anzuziehen. Andere hingegen nutzen diese Aasjäger, um Diebe abzuhalten. Nicht wenige Diebe haben die Beutel schlafender Riesen durchwühlt, nur um an der klebrigen Oberfläche einer Beutelgallerte klebenzubleiben und nicht fliehen zu können, als der Riese vom Kampflärm erwachte."
