    beschreibung: [
      "Blitzkolosse sind die Nachkommen von Sturmriesen, die sich in fernen Zeiten aus der Welt zurückzogen. Im Lauf der Jahrhunderte wuchs die elementare Natur dieser Riesen an – befeuert durch entsprechende Zuführungen von Energie aus den Elementarebenen. Schließlich gewann diese Natur ganz die Oberhand über die Riesen und befreite sie vollständig von den Einschränkungen des Fleischs.",
      "Ein Blitzkoloss ist im Wesentlichen ein lebender Blitz, und die einzige verbliebene Spur seiner früheren Natur ist ein vage zu erkennendes Gesicht, das an der Spitze des Blitzes erscheint, wenn er durch die Luft strömt. In seltenen Momenten verfestigt sich der Koloss zu einer zweibeinigen Gestalt, die einem Sturmriesen ähnelt, doch diese Augenblicke sind ebenso flüchtig wie ein Blitzeinschlag.",
      "Zu anderen Zeiten, insbesondere in der Nähe von Metall oder fester Erde, scheint der Koloss kurz davor zu stehen, sich vollständig zu zerstreuen und das letzte bisschen Zusammenhalt zu verlieren, das ihn überhaupt zu einer eigenständigen Wesenheit macht. Seine geistige Verfassung ist ähnlich zerfasert: Ein Blitzkoloss rast von einem Ort zum anderen, ohne wirkliches Ziel und ohne einen Hauch jener Nachdenklichkeit, die seine entfernten riesischen Verwandten so sehr beschäftigt."
    ],
