      { name: "Blitzgestalt", beschreibung: "Der Blitzkoloss kann in den Bereich einer feindlich gesinnten Kreatur eindringen und dort stoppen. Wenn er erstmals im Zug den Bereich einer Kreatur betritt oder seinen Zug im Bereich einer Kreatur beginnt, erleidet diese 7 (2W6) Blitzschaden. Der Koloss kann sich durch einen engen Bereich mit einer Breite von nur 2,5 Zentimetern bewegen, ohne sich quetschen zu müssen. Eine Kreatur, die den Blitzkoloss berührt oder mit einem Nahkampfangriff trifft, während sie sich im Abstand von bis zu 1,5 Metern von ihm befindet, erleidet 7 (2W6) Blitzschaden." }
