      "Manchen Legenden zufolge waren die ersten Ettin einst Orks, verwandelt von Demogorgon, dem Prinzen der Dämonen. Andere sehen ihre Ursprünge bei Grolantor oder einem anderen Gott des Ordnings. Wie die Wahrheit auch aussehen mag, Ettin sehen im zweiköpfigen Demogorgon manchmal eine verwandte Seele und treten in seine Dienste. Wer sich für Demogorgons Zwecke auf der materiellen Ebene als besonders nützlich erweist, wird mit einem „Segen“ belohnt, der ihn in ein monströses Echo des dämonischen Schutzherrn verwandelt.",
      "Die Hände eines Echos von Demogorgon verwandeln sich in mächtige Tentakel, und die Köpfe nehmen ein tierisches Aussehen an. Die Verwandlung versetzt das Echo in Kampfrausch. Die beiden Köpfe heulen und brüllen einander an, und im Zorn schwingt die dämonische Magie mit und sorgt im Umkreis für Streit und Verwirrung. Wenn die monströsen Köpfe des Echos brüllen und nacheinander schnappen, leiden Kreaturen in der Nähe unter psychischen Schmerzen oder stimmen in den Radau ein und greifen ihre Verbündeten an."
