      "Ein Feuerriese, dessen brennender Hass ihn daran hindert, das Jenseits zu erreichen, erhebt sich als Feuerknochen. Entstanden aus tiefem Groll, forscht der Feuerknochen nach lebendigen Kreaturen, die er zerstören kann. Wie ein Schreckgespenst sucht auch er keine Rache, sondern will nur so viel Zerstörung wie möglich anrichten, ehe er ins endgültige Vergessen eingeht.",
      "Ein Feuerknochen sieht wie ein schwer verbrannter Leichnam aus. Übernatürliche purpurrote Flammen kreisen in seinen Adern, brechen aus seinen Wunden und seinem Mund hervor."
