      { name: "Purpurrote Strahlen (Aufladung 5–6)", beschreibung: "Der Feuerknochen verschießt Feuerstrahlen in einem Kegel von neun Metern aus den Augen, dem Mund und seinen Wunden. Jede Kreatur in diesem Bereich muss einen SG-18-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 31 (7W8) Feuerschaden, anderenfalls die Hälfte. Unabhängig vom Ergebnis fängt die Kreatur Feuer. Bis die brennende Kreatur oder eine andere Kreatur, die sie erreichen kann, das Feuer mit einer Aktion löscht, kann die brennende Kreatur keine Trefferpunkte zurückerhalten und erleidet zu Beginn jedes ihrer Züge 5 (1W10) Feuerschaden." }
