    fertigkeiten: { "Athletik": 13, "Wahrnehmung": 11 },
    schadensresistenzen: [],
    schadensimmunitaeten: ["Feuer"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: [],
    sinne: [],
    passiveWahrnehmung: 21,
    sprachen: ["Gemeinsprache", "Riesisch"],
    umgebung: ["Andere Ebenen", "Gebirge", "Unterirdisch"],
    bild: "assets/images/monster/ruhm-der-riesen/feuerriesen-schmiedenrufer.png",
    beschreibung: [
      "Ein Feuerriese, der traditionelle Runenmagie beherrscht, kann die Hitze von Vulkanen kontrollieren und aus Feuer und Magma rohe Elementarenergie beschwören. In Gemeinschaften von Feuerriesen kümmern sich diese Schmiedenrufer sowohl um die Öfen als auch um die Verteidigung der Gemeinschaft, oft in Surturs Namen. Manche Schmiedenrufer ziehen es vor, in Isolation zu leben und zu arbeiten. Dazu suchen sie die heißesten Feuer im Herzen von Vulkanen oder aber die Elementarebene des Feuers auf, um ihre Werke und Studien voranzutreiben.",
      "Ein Schmiedenrufer ist ein wandelnder Hochofen, von Kopf bis Fuß in eine Ritterrüstung gehüllt, die der intensiven Hitze und dem sengenden Rauch kaum standhalten kann. Schmiedenrufer beschwören Magmawogen und können fliegen, indem sie magisches Feuer aus ihren Beinen und Körpern ausstoßen."
    ],
    besonderheiten: [
      { name: "Feuerrune", beschreibung: "Der Riese besitzt eine Feuerrune, die in ein Medaillon oder einen anderen Gegenstand in seinem Besitz eingraviert wurde. Solange er den Gegenstand mit der Rune trägt oder hält, kann er seine Magmawoge-Aktion und die Hochofenrüstung-Bonusaktion verwenden. Der Gegenstand mit der Rune besitzt eine RK von 15, 40 Trefferpunkte und ist gegen Giftschaden, nekrotischen Schaden und psychischen Schaden immun. Er erhält am Ende jedes Zugs alle Trefferpunkte zurück, zerfällt jedoch zu Staub, wenn seine Trefferpunkte auf 0 sinken oder der Riese stirbt. Wenn die Rune zerstört wird, kann der Riese nach einer kurzen oder langen Rast eine Feuerrune in einen anderen Gegenstand in seinem Besitz gravieren." },
      { name: "Legendäre Resistenz (3/Tag)", beschreibung: "Scheitert ein Rettungswurf des Riesen, kann er den Wurf in einen Erfolg verwandeln." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Riese führt drei Schmiedehammer- oder zwei Erhitzter-Felsblock-Angriffe aus." },
      { name: "Schmiedehammer", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 24 (5W6+7) Wuchtschaden. Treffer oder Fehlschlag: Der Riese kann mit dem Hammer eine Hitzeexplosion in einer Kugel mit einem Radius von neun Metern um das Ziel bewirken. Gegenstände aus Metall in diesem Bereich glühen bis zum Beginn des nächsten Zugs des Riesen rot. Kreaturen, die am Anfang ihres Zugs in physischen Kontakt mit einem erhitzten Gegenstand kommen, müssen einen SG-19-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, so erleiden sie 10 (3W6) Feuerschaden und sind bis zum Anfang ihres nächsten Zugs bei Angriffswürfen im Nachteil, sofern sie nicht gegen Feuerschaden immun sind. Der Hammer kann nur einmal pro Zug auf diese Art Hitze abgeben." },
      { name: "Erhitzter Felsblock", beschreibung: "Fernkampfwaffenangriff: +13 auf Treffer, Reichweite 18/72 m, ein Ziel. Treffer: 23 (3W10+7) Wuchtschaden plus 19 (3W12) Feuerschaden. Wenn das Ziel eine höchstens große Kreatur ist, muss es einen SG-21-Stärkerettungswurf bestehen, oder es wird umgestoßen. Würfle mit einem W6, nachdem der Riese den Felsblock geworfen hat. Bei einem Ergebnis von höchstens 3 hat der Riese keine weiteren Felsblöcke, die er werfen könnte." },
      { name: "Magmawoge (erfordert Feuerrune)", beschreibung: "Der Riese entfesselt mit seiner Feuerrune eine Magmawoge in einem Kegel von neun Metern. Jede Kreatur in diesem Bereich muss einen SG-19-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 36 (8W8) Feuerschaden und ist festgesetzt. Eine Kreatur kann als Aktion einen SG-19-Stärkewurf (Athletik) ausführen. Bei einem Erfolg kann sie sich oder eine Kreatur in Reichweite vom Felsblock befreien. Der Felsblock, der eine Kreatur festsetzt, besitzt eine RK von 17, 20 Trefferpunkte und ist gegen Feuer-, Gift- und psychischen Schaden immun. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden." }
    ],
    bonusaktionen: [
      { name: "Hochofenrüstung (erfordert Feuerrune)", beschreibung: "Der Riese lässt Rauch und Funken aus seiner Rüstung dringen, die eine Kugel mit einem Radius von neun Metern um den Riesen erfüllen. Während die Rüstung Rauch von sich gibt, hat der Riese Teildeckung. Die Rüstung hört nach einer Minute auf, Rauch abzusondern, oder aber wenn der Riese stirbt, eine Bonusaktion verwendet, um den Effekt zu beenden, oder wenn seine Feuerrune zerstört wird." }
    ],
