    beschreibung: [
      "Als entfernte Verwandte der Riesen wanderten die ersten Firbolg aus den urtümlichen Wäldern des Multiversums ein, und die Magie dieser Wälder verband sich mit ihren Seelen. Äonen später vibriert die Magie noch immer in ihnen.",
      "Firbolg treten oft in die Dienste der Göttinnen Diancastra und Hiatea oder versuchen ihnen nachzueifern. Ihre innere Magie der Undurchsichtigkeit und List korrespondiert mit Diancastras raffinierter Findigkeit. Ihre traditionelle Wertschätzung für Gemeinschaft und Harmonie bringt wiederum viele Firbolg dazu, sich in Hiateas Dienste zu stellen.",
      "Wie die riesischen Priester von Hiatea nehmen auch Firbolg, die ihr dienen, eine von zwei sehr verschiedenen Rollen an. Dies entspricht Hiateas dualer Natur. Zuhause kümmern sich urtümliche Wächter um die Herde und um die Ausbildung der Jugend. Urwächter auf Patrouille an den Grenzen der Firbolg-Gemeinschaften sind wilde Jäger und beschützen die Grenzen vor Eindringlingen und äußeren Bedrohungen."
    ],
    besonderheiten: [],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Firbolg führt zwei Speer- oder Feuerlanzenangriffe aus." },
      { name: "Speer", beschreibung: "Nah- oder Fernkampfwaffenangriff: +5 auf Treffer, Reichweite 1,5 m oder Reichweite 6/18 m, ein Ziel. Treffer: 6 (1W6+3) Stichschaden plus 9 (2W8) Feuerschaden." },
      { name: "Feuerlanze", beschreibung: "Fernkampf-Zauberangriff: +5 auf Treffer, Reichweite 36 m, ein Ziel. Treffer: 14 (2W10+3) Feuerschaden." },
      { name: "Zauberwirken", beschreibung: "Der Firbolg wirkt einen der folgenden Zauber und verwendet Weisheit als Attribut zum Zauberwirken (Zauberrettungswurf-SG 13). Beliebig oft: Mit Pflanzen sprechen, Mit Tieren sprechen, Verstricken. Je 1-mal täglich: Einswerden mit der Natur (als Aktion), Magie entdecken, Selbstverkleidung." }
    ],
    bonusaktionen: [
      { name: "Verborgener Schritt (2/Tag)", beschreibung: "Der Firbolg wird auf magische Weise unsichtbar: bis zum Beginn seines nächsten Zugs, bis er einen Angriffswurf ausführt oder bis er jemanden zu einem Rettungswurf zwingt." }
    ],
