      "Firbolg treten oft in die Dienste der Göttinnen Diancastra und Hiatea oder versuchen ihnen nachzueifern. Ihre innere Magie der Undurchsichtigkeit und List korrespondiert mit Diancastras raffinierter Findigkeit. Ihre traditionelle Wertschätzung für Gemeinschaft und Harmonie bringt wiederum viele Firbolg dazu, sich in Hiateas Dienste zu stellen.",
