    attribute: { STR: 24, DEX: 9, CON: 24, INT: 6, WIS: 10, CHA: 5 },
    rettungswuerfe: {},
    fertigkeiten: {},
    schadensresistenzen: [],
    schadensimmunitaeten: ["Blitz", "Gift", "Psychisch", "Hieb-, Stich- und Wuchtschaden durch nichtmagische Angriffe"],
    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Gelähmt", "Verängstigt", "Vergiftet", "Versteinert"],
    sinne: ["Dunkelsicht 36 m"],
    passiveWahrnehmung: 10,
    sprachen: ["Versteht Riesisch, aber kann nicht sprechen"],
    umgebung: [],
    bild: "assets/images/monster/ruhm-der-riesen/fleischkoloss.png",
    beschreibung: [
      "Als die riesischen Imperien entstanden, wollten verdrehte Geister dafür sorgen, dass ihre gefallenen Kameraden den Dienst fortsetzten. Riesische Magier nähten und webten das Fleisch verschiedener Riesen an ein Adamantskelett und schufen ein riesiges grässliches Konstrukt. In der Brust des Fleischkolosses liegt eine Steinkugel mit Geistern von jeder Elementarebene, die als ihr Kern fungieren.",
      "Bis heute bewachen einige dieser Fleischkolosse verlassene Ruinen, Stätten, die Riesen heilig sind, und verlorene Schätze – und womöglich auch das Verfahren, mit dem sich mehr von ihresgleichen erzeugen lassen."
    ],
    besonderheiten: [
      { name: "Belagerungsmonster", beschreibung: "Der Koloss fügt Gegenständen und Gebäuden den doppelten Schaden zu." },
      { name: "Berserker", beschreibung: "Wenn der Kern im Koloss zerstört wird, gerät der Koloss in Kampfrausch. Dabei greift der Koloss die Kreatur an, die ihm am nächsten ist und die er sehen kann. Befindet sich keine Kreatur in Angriffsreichweite, so greift der Koloss einen Gegenstand an. Wenn der Koloss einmal in Kampfrausch gerät, behält er diesen Zustand bei, bis er zerstört wird." },
      { name: "Magieresistenz", beschreibung: "Der Koloss ist bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil." },
      { name: "Unveränderliche Gestalt", beschreibung: "Der Koloss ist gegen alle Zauber und Effekte immun, die seine Gestalt verändern würden." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Koloss führt zwei Faustangriffe aus." },
      { name: "Faust", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer (im Vorteil, wenn der Koloss im Kampfrausch ist), Reichweite 6 m, ein Ziel. Treffer: 17 (3W6+7) Wuchtschaden. Wenn das Ziel eine höchstens große Kreatur ist, wird es bis zu 4,5 Meter zum Koloss hingezogen, wird gepackt (Rettungswurf-SG 17) und festgesetzt, bis es nicht mehr gepackt ist. Der Koloss kann jeweils zwei Kreaturen auf diese Art gepackt halten." },
      { name: "Elementarodem (Aufladung 5–6)", beschreibung: "Der Koloss atmet eine Wolke voller Elementarenergie in einem Kegel von 27 Metern aus. Jede Kreatur in diesem Bereich muss einen SG-21-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 40 (9W8) Schaden nach Wahl des Kolosses: Blitz, Feuer, Kälte oder Säure. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden. Wenn der Koloss seinen Odem freisetzt, erleiden Kreaturen in seiner Brusthöhle 40 (9W8) Energieschaden durch die mahlende Elementarenergie." }
    ],
    bonusaktionen: [
      { name: "Biss", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 1,5 m, eine höchstens große Kreatur, die vom Koloss gepackt wurde. Treffer: 20 (3W8+7) Wuchtschaden, und die Kreatur wird verschluckt. Eine verschluckte Kreatur ist festgesetzt, hat vollständige Deckung gegen Angriffe und andere Effekte von außerhalb des Kolosses und erleidet zu Beginn jedes Zugs des Kolosses 10 (3W6) Energieschaden. In die Brusthöhle des Kolosses passen bis zu zwei Kreaturen auf einmal. In der Brusthöhle befindet sich auch der Kern des Kolosses. Dieser ist ein großer Gegenstand, besitzt eine RK von 16 und ist gegen Blitz-, Gift- und psychischen Schaden immun. Er hat 140 Trefferpunkte und verbreitet im Radius von drei Metern dämmriges Licht. Wenn der Kern zerstört wird, würgt der Koloss alle verschluckten Kreaturen wieder aus. Diese finden sich dann in einem Bereich von drei Metern um den Koloss herum wieder und sind liegend, und der Koloss kann keine Kreaturen mehr verschlucken. Wenn der Koloss stirbt, sind die verschluckten Kreaturen nicht mehr festgesetzt und können aus der Leiche entkommen. Sie verwenden dazu drei Meter ihrer Bewegungsrate und sind dann liegend." }
    ],
