      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 22 (3W10+6) Wuchtschaden." },
      { name: "Kriecherverwünschen (Aufladung 4–6)", beschreibung: "Der Fomorianer zielt auf eine Kreatur im Abstand von bis zu 18 Metern von sich, die er sehen kann. Das Ziel muss einen SG-15-Weisheitsrettungswurf bestehen, oder es erleidet 31 (7W8) psychischen Schaden, ist liegend und eine Stunde lang verflucht. Während das Ziel auf diese Art verflucht ist, kann es nicht aufstehen und seinen Liegend-Zustand beenden." }
