    beschreibung: [
      "Fomorianer stammen von Annams Sohn Karontor ab und nahmen im riesischen Ordning einst einen Platz zwischen Hügel- und Steinriesen ein. In uralten Zeiten waren sie Gelehrte der Magie und für ihren scharfen Intellekt berühmt – allerdings auch für ihre Einbildung und Arroganz. Karontor nutzte diese Eigenschaften aus, lockte die Fomorianer mit einem höheren Rang im Ordning und stiftete sie zu einem Angriff auf das Feywild an. Als dieser fehlschlug, wurden die Fomorianer ins Unterreich verbannt, und ihr Gott wurde in einen unterirdischen Kerker gesperrt. In der merkwürdigen Magie des Unterreichs veränderten sich die Fomorianer körperlich und seelisch, bis sie zu den Fomorianern wurden, die man heute kennt.",
      "Vor ihrer Verbannung ins Unterreich legten die Fomorianer ihre Rangfolge nach erworbenem Wissen und magischen Kräften fest. Ehe Karontor seine Nachfahren zu jenem schicksalhaften Angriff auf das Feywild drängte, waren manche der ambitioniertesten, wissbegierigsten und machthungrigsten Fomorianer der Ansicht, dass sie auf der materiellen Ebene nichts mehr lernen konnten, und sie brachen auf zu den Inneren Ebenen, um dort ihre Suche nach Wissen ungehindert fortzusetzen.",
      "In ihrer Arroganz entgingen diese fomorianischen Adeligen nichtsahnend dem grausigen Schicksal ihrer Brüder und blieben in den fernen Enklaven unverändert. Gelegentlich kehren sie auf die materielle Ebene zurück, um die Welt zu beobachten, die sie einst verlassen haben. Mit ihren spitzen Zügen und alterslosen Gesichtern sehen diese Fomorianer aus wie riesige Elfen."
    ],
    besonderheiten: [],
