    beschreibung: [
      "Wenn ein Frostriese auf unehrenhafte Weise getötet – vielleicht vergiftet, von hinten erstochen oder im Schlaf ermordet – wird, erhebt er sich möglicherweise als Frostklage. Diese ist von Rachedurst getrieben und kann lebendige Wesen mit einer Berührung in gefrorene Statuen verwandeln oder Gegner mit eisigem Wind ausbremsen. Rache reicht nicht immer, um diesen Kreaturen Ruhe zu gewähren. Oft reicht ihr Hass auf die Lebenden so tief, dass sie noch Jahre, nachdem ihre Mörder getötet wurden, durch die Wildnis streifen.",
      "Eine Frostklage sieht aus wie eine vertrocknete Leiche, die durch bittere Kälte mumifiziert wurde. Sie trägt die Zeichen ihres Todes am Körper: eine Wunde, die frostige Dämpfe freisetzt, oder strahlend rote Adern, die die Verheerungen durch das Gift zeigen. Außerdem kann sie ihren Körper vorübergehend in einen wirbelnden Schneesturm auflösen, um Schaden zu vermeiden, und sich dann in sicherer Entfernung wieder verfestigen, um ihre Angriffe fortzusetzen."
    ],
    besonderheiten: [],
