      { name: "Eisige Axt", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 19 (3W8+6) Hiebschaden plus 7 (2W6) Kälteschaden." },
      { name: "Eisige Berührung", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 1,5 m, eine Kreatur. Treffer: 18 (4W8) Kälteschaden plus 18 (4W8) nekrotischer Schaden. Werden die Trefferpunkte des Ziels durch diesen Schaden auf 0 verringert, so bleibt stattdessen 1 Trefferpunkt übrig, und das Ziel wird versteinert, weil es in eine Eisstatue verwandelt wird. Erleidet die Statue Wuchtschaden, so zerbricht sie, und die gefrorene Kreatur stirbt. Würde die Statue Feuerschaden erleiden, so erleidet sie keinen Schaden und taut stattdessen auf, wodurch die Versteinerung aufgehoben wird." },
      { name: "Polarstrahl", beschreibung: "Fernkampf-Zauberangriff: +8 auf Treffer, Reichweite 36 m, ein Ziel. Treffer: 31 (5W10+4) Kälteschaden, und die Bewegungsrate des Ziels ist bis zum Ende seines nächsten Zugs um drei Meter verringert." }
