      { name: "Froststrahl", beschreibung: "Fernkampf-Zauberangriff: +10 auf Treffer, Reichweite 36 m, ein Ziel. Treffer: 17 (3W8+4) Kälteschaden, und das Ziel muss einen SG-18-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, so ist das Ziel bis zum Ende seines nächsten Zugs festgesetzt. Bei einem erfolgreichen Rettungswurf ist die Bewegungsrate des Ziels bis zum Ende seines nächsten Zugs um drei Meter verringert." },
      { name: "Eiswölfe (erfordert Frostrune)", beschreibung: "Der Riese beschwört magisch 1W4 Wölfe aus Eis (verwende den Wertekasten des Winterwolfs im Monsterhandbuch, um sie zu repräsentieren – allerdings sind sie Elementare, keine Monstrositäten). Die Wölfe erscheinen an freien Stellen im Abstand von bis zu neun Metern vom Riesen, die er sehen kann. Die Züge der Wölfe finden sofort nach denen des Riesen und mit demselben Initiativewert statt, und die Wölfe gehorchen den Befehlen des Riesen. Die Wölfe erhalten einen Bonus von +6 auf ihre Angriffs- und Schadenswürfe, solange sie sich im Abstand von bis zu neun Metern vom Riesen befinden. Sie verschwinden nach einer Minute, wenn der Riese stirbt oder diese Aktion erneut einsetzt." }
