    umgebung: ["Gebirge"],
    bild: "assets/images/monster/ruhm-der-riesen/geisterwolke.png",
    beschreibung: [
      "Ein Wolkenriese, der durch einen Akt des Verrats oder eine unglückliche Wette stirbt, kehrt manchmal als Geisterwolke zurück. Dieser Untote scheint nur eine dicke Wolke oder Nebelbank zu sein, doch aufmerksame Beobachter entdecken bisweilen eine schattenhafte, zweibeinige Gestalt, die darin lauert. Im Herzen der Wolke wird das Aussehen der Gestalt dann erkennbar: der skeletthafte Leichnam eines Wolkenriesen.",
      "Manche Geschichten erzählen davon, dass Wolkenriesen dieses Schicksal sogar ab und an suchen, anstatt das Ende ihres von Natur aus langen Lebens hinzunehmen. In solchen Geschichten durchläuft der Wolkenriese ein Ritual, bei dem sein Herz in eine Wolke verpflanzt wird, wodurch sich der Körper des Riesen auflöst und sein Geist die Wolke belebt."
    ],
    besonderheiten: [
      { name: "Körperlose Bewegung", beschreibung: "Die Geisterwolke kann sich durch andere Kreaturen und Gegenstände bewegen, als wären sie schwieriges Gelände. Sie erleidet 5 (1W10) Energieschaden, wenn sie ihren Zug in einem Gegenstand beendet." },
      { name: "Verschwommene Gestalt", beschreibung: "Angriffswürfe gegen die Geisterwolke sind im Nachteil, es sei denn, der Angreifer befindet sich im Abstand von bis zu 4,5 Metern von der Geisterwolke, oder diese ist kampfunfähig." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Geisterwolke führt zwei Geisterhafte-Berührung-Angriffe aus." },
      { name: "Geisterhafte Berührung", beschreibung: "Nahkampfwaffenangriff: +12 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 20 (3W8+7) Energieschaden plus 10 (3W6) nekrotischer Schaden. Wenn das Ziel eine Kreatur ist, muss es einen SG-20-Konstitutionsrettungswurf bestehen, oder sein Trefferpunktemaximum wird um die Höhe des erlittenen nekrotischen Schadens verringert. Es bleibt verringert, bis das Ziel eine lange Rast beendet. Wird das Trefferpunktemaximum auf 0 verringert, stirbt das Ziel. Wird ein Humanoid durch diesen Angriff getötet, so erhebt er sich sofort als kleine Geisterwolke (siehe Wertekasten des Schreckgespensts im Monsterhandbuch). Die kleine Geisterwolke handelt als Verbündete der Geisterwolke, wird jedoch nicht von ihr kontrolliert." },
      { name: "Eisige Winde (Aufladung 5–6)", beschreibung: "Die Geisterwolke atmet sehr kalten Wind in einer 18 Meter langen und drei Meter breiten Linie aus. Jede Kreatur in diesem Bereich muss einen SG-20-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 38 (7W10) Kälteschaden und ist eine Minute lang kampfunfähig. Die betroffene Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und den Effekt bei einem Erfolg beenden. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden. Wenn eine Kreatur ihren Rettungswurf besteht oder der Effekt auf sie endet, ist sie 24 Stunden lang gegen die Eisigen Winde dieser Geisterwolke immun." }
    ],
