    bild: "assets/images/monster/ruhm-der-riesen/gigant.png",
    beschreibung: [
      "Ein Gigant ist eine hoch aufragende, insektenartige Kreatur, die als Vorbote des Untergangs, Verteidiger der Natur und göttlicher Bote mit rätselhaften Absichten angesehen wird. Riesen betrachten sie als Plage, denn Giganten verspeisen nichts lieber als Riesen. Einige Riesen behaupten, Giganten würden durch jene sonderbare magische Aura erschaffen, die eine Gargantua umgibt.",
      "Ein Gigant ähnelt einem riesigen Käfer, dessen Beine in scharfen Krallen enden. Er benutzt seine Krallen, um Kreaturen zu seinen gewaltigen Kiefern zu befördern. Diese sind stark genug, um einen Riesen zu packen und ihn anschließend zum Nest des Giganten zu tragen, damit er dort verschlungen werden kann.",
      "Die Flügel eines Giganten sind üblicherweise unter seinem Panzer gefaltet, doch der schnelle Flieger kann auch mit den Flügeln schlagen, um einen schrecklichen Ton zu erzeugen oder einen giftigen Staub zu verbreiten."
    ],
    besonderheiten: [
      { name: "Zauberresistenter Panzer", beschreibung: "Der Gigant ist bei Rettungswürfen gegen Zauber im Vorteil, und Zauberangriffe gegen den Giganten sind beim Angriffswurf im Nachteil." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Gigant führt einen Kieferangriff und zwei Krallenangriffe aus." },
      { name: "Kiefer", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 1,5 m, eine Kreatur. Treffer: 21 (4W6+7) Hiebschaden, und das Ziel wird gepackt (Rettungswurf-SG 17). Ein gepacktes Ziel erleidet zu Beginn jedes Zugs des Giganten 21 (4W6+7) Hiebschaden, bis das Packen endet. Solange der Gigant ein Ziel gepackt hat, kann er seinen Kieferangriff nicht gegen andere Ziele verwenden." },
      { name: "Krallen", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 6 m, ein Ziel. Treffer: 17 (3W6+7) Hiebschaden, und das Ziel wird drei Meter in gerader Linie zum Giganten hingezogen." },
      { name: "Schuppenstaub (Aufladung 5–6)", beschreibung: "Der Gigant gibt in einem Würfel von neun Metern Kantenlänge magischen Staub von seinen Flügeln ab. Jede Kreatur in diesem Bereich muss einen SG-19-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 45 (10W8) Giftschaden, anderenfalls die Hälfte. Unabhängig vom Ergebnis ist die Kreatur eine Stunde lang vergiftet. Solange sie auf diese Art vergiftet ist, kann die Kreatur keine Trefferpunkte zurückerhalten." }
    ],
    bonusaktionen: [
      { name: "Dröhnen", beschreibung: "Der Gigant erzeugt ein schreckliches Dröhnen, indem er schnell mit den Flügeln schlägt. Jede Kreatur im Abstand von bis zu drei Metern um den Giganten muss einen SG-19-Konstitutionsrettungswurf bestehen, oder sie erleidet 10 (3W6) Schallschaden und ist bis zum Ende ihres nächsten Zugs kampfunfähig. Der Gigant kann dann bis zur Hälfte seiner Flugbewegungsrate fliegend zurücklegen." }
    ],
