    beschreibung: [
      "Ein Hügelriese, der mit leerem Magen und voller Wut und Reue stirbt, kann mit Energie der negativen Ebene durchdrungen werden und sich als Grab-Grul erheben. Dieser sieht zwar aus wie eine belebte Leiche, ist jedoch mit nekrotischer Energie angefüllt und wird von Hass und Bosheit angetrieben. Sein Blut ist ein dickflüssiges giftiges Sekret, das den Grab-Grul übel stinken lässt.",
      "Grab-Grule gieren nicht mehr nach physischer Nahrung, sondern beziehen ihre Lebensenergie aus lebendigen Kreaturen. Oft greifen sie auf die Lebensenergie ehemaliger Familienmitglieder und Verbündeter zurück, laben sich aber praktisch an allen Kreaturen, denen sie begegnen. Wenn Grab-Grule die Lebensenergie von Humanoiden komplett verzehren, erheben diese sich als Zombies."
    ],
    besonderheiten: [
      { name: "Gestank", beschreibung: "Alle Kreaturen, die ihren Zug im Abstand von bis zu drei Metern vom Grab-Grul beginnen, müssen einen SG-16-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, so ist die Kreatur eine Minute lang vergiftet. Solange sie auf diese Art vergiftet ist, kann die Kreatur keine Trefferpunkte zurückerhalten. Bei einem erfolgreichen Rettungswurf ist die Kreatur 24 Stunden lang gegen den Gestank aller Grab-Grule immun." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Grab-Grul führt zwei Hiebangriffe aus. Er kann einen Hiebangriff durch einen Lebensentzug-Angriff ersetzen." },
      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +8 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 18 (2W12+5) Wuchtschaden." },
      { name: "Lebensentzug", beschreibung: "Nahkampfwaffenangriff: +8 auf Treffer, Reichweite 3 m, eine Kreatur. Treffer: 9 (1W8+5) nekrotischer Schaden, und das Ziel muss einen SG-16-Konstitutionsrettungswurf bestehen, oder sein Trefferpunktemaximum wird um einen Betrag in Höhe des erlittenen Schadens verringert. Es bleibt verringert, bis das Ziel eine lange Rast beendet. Wenn das Trefferpunktemaximum durch diesen Effekt auf 0 sinkt, stirbt das Ziel. Wird ein Humanoid durch diesen Angriff getötet, so erhebt er sich sofort als Zombie (siehe Monsterhandbuch). Der Zombie handelt als Verbündeter des Grab-Gruls, wird jedoch nicht von ihm kontrolliert." }
    ],
    bonusaktionen: [],
