    sprachen: ["Gemeinsprache", "Sylvanisch"],
    umgebung: ["Wald", "Feenwildnis"],
    bild: "assets/images/monster/ruhm-der-riesen/grinsekatze.png",
    beschreibung: [
      "Grinsekatzen sind schelmische Feenwesen, die es lieben, Reisende zu belästigen und in die Irre zu führen. Sie ähneln übergroßen Hauskatzen mit langen, nadelartigen Krallen, doch sie zeichnen sich durch das breite Lächeln voller Zähne aus, das ihnen ihren Namen verleiht.",
      "Grinsekatzen leben oft in riesischen Enklaven oder in deren Nähe. Den Großteil ihrer Zeit verbringen sie unsichtbar und faulenzen auf Ästen, bis Beute oder ein möglicher Gesprächspartner vorbeikommt. Beim Austausch von Rätseln oder Witzen beschließen solche Katzen oft, ihr Grinsen, ihren Schwanz oder manchmal auch den ganzen Kopf zu zeigen, um ihren Gesprächspartner zu verwirren oder einzuschüchtern.",
      "Eine Grinsekatze lässt sich gelegentlich überreden, eines ihrer Schnurrhaare zu verschenken. Eine Kreatur, die ein Schnurrharr hält, kann es verwenden, um einmal den Zauber Nebelschritt zu wirken. Danach löst sich das Schnurrharr in Rauch auf. Wird eine Grinsekatze erschlagen, finden sich 2W12 ihrer Schnurrhaare, die sich auf die genannte Weise verwenden lassen."
    ],
    besonderheiten: [
      { name: "Magieresistenz", beschreibung: "Die Grinsekatze ist bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil." }
    ],
    aktionen: [
      { name: "Biss", beschreibung: "Nahkampfwaffenangriff: +4 auf Treffer, Reichweite 1,5 m, ein Ziel. Treffer: 7 (1W10+2) Stichschaden." },
      { name: "Klauen", beschreibung: "Nahkampfwaffenangriff: +4 auf Treffer, Reichweite 1,5 m, ein Ziel. Treffer: 9 (2W6+2) Hiebschaden. War die Grinsekatze vor dem Angriff unsichtbar, muss das Ziel einen SG-12-Stärkerettungswurf bestehen, oder es wird umgestoßen. Wenn das Ziel liegend ist, kann die Katze als Bonusaktion einen Bissangriff gegen es ausführen." },
      { name: "Verblassen", beschreibung: "Die Grinsekatze wird eine Stunde lang oder bis sie angreift auf magische Weise unsichtbar und verschwindet im Lauf ihres Zugs allmählich. Sie kann einen Teil ihres Körpers sichtbar lassen, etwa ihren Schwanz, ihren Kopf oder ihr grinsendes Maul. Ausrüstung, die die Katze trägt oder hält, ist ebenfalls unsichtbar." }
    ],
    bonusaktionen: [
      { name: "Entblassen", beschreibung: "Die Grinsekatze wird vollständig sichtbar oder macht einen Teil ihres Körpers sichtbar. Ausrüstung, die die Katze an einem sichtbaren Teil trägt oder hält, wird ebenfalls sichtbar." },
      { name: "Grinseschritt", beschreibung: "Die Grinsekatze teleportiert sich und sämtliche Ausrüstung, die sie trägt oder hält, bis zu 18 Meter weit an eine freie Stelle, die sie sehen kann." }
    ],
