    bild: "assets/images/monster/ruhm-der-riesen/nachkomme_von_grolantor.png",
    beschreibung: [
      "Riesen stammen vom Allvater Annam und dessen Kindern ab. Doch Nachkommen der riesischen Götter protzen mit einem gewichtigeren Anspruch: Sie sind Annams Enkel und nehmen dadurch einen privilegierten Platz unter den Riesen ein. Auf einigen Welten herrschten diese Nachkommen über die ersten riesischen Reiche, bis sich Annam in die Abgeschiedenheit zurückzog. Auf anderen Welten bewachen die Nachkommen ihre Geburtsstätten, die reich an elementarer Magie sind, oder halten die Substanz der Welt zusammen.",
      "Nachkommen der riesischen Götter sind ungeheuer mächtige Wesen, die die Welt um sich herum mit urtümlicher Magie erfüllen. Sie schlummern in vielen Welten und sind dort Teil der Landschaft geworden. In solch einem Fall liegt der Nachkomme in Stase und wird von einem mächtigen Elementar umhüllt, den man eine Wiege nennt. Die Wiege schützt den schlummernden Nachkommen und folgt seinen unterbewussten Wünschen, einschließlich der Vertreibung von Eindringlingen. Doch falls die Wiege stirbt, erwacht der Nachkomme darin ganz.",
      "Ein schlummernder Nachkomme von Grolantor wird oft mit einem Hügel verwechselt, und manchmal errichten Menschen Hinkelsteine, ein Dorf oder eine Stadt auf dem Rücken eines Nachkommen, ohne sich der großen Macht unter ihren Füßen bewusst zu sein. Solche Siedlungen erleben oft jahrhundertelange Blütezeiten, da die Magie des Nachkommen dafür sorgt, dass in der umliegenden Region Feldfrüchte und Vieh besonders gut gedeihen. Ein uralter Baum überragt die Hügelkuppe.",
      "Wird die Wiege vernichtet, erwacht der Nachkomme von Grolantor. 15 Meter ragt der Nachkomme in die Höhe und verschlingt alles in Reichweite, um seinen Hunger zu stillen. Seine kräftigen Lungen können Nahrung direkt in seinen Magen saugen. Mit einem Baum schlägt der Nachkomme seine Feinde weit von sich weg."
    ],
    besonderheiten: [
      { name: "Belagerungsmonster", beschreibung: "Der Nachkomme fügt Gegenständen und Gebäuden den doppelten Schaden zu." },
      { name: "Legendäre Resistenz (6/Tag)", beschreibung: "Wenn sein Rettungswurf scheitert, kann der Nachkomme den Wurf in einen Erfolg verwandeln." },
      { name: "Magieresistenz", beschreibung: "Der Nachkomme ist bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Nachkomme führt zwei Hiebangriffe und einen Mammutbaumknüppelangriff aus, oder er führt drei Felswurf-Angriffe aus." },
      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +15 auf Treffer, Reichweite 6 m, ein Ziel. Treffer: 26 (4W8+8) Energieschaden." },
      { name: "Mammutbaumknüppel", beschreibung: "Nahkampfwaffenangriff: +15 auf Treffer, Reichweite 9 m, ein Ziel. Treffer: 30 (4W10+8) Wuchtschaden. Wenn das Ziel eine Kreatur ist, muss es einen SG-23-Stärkerettungswurf bestehen, oder es wird 30 Meter in gerader Linie vom Nachkommen weg- und umgestoßen." },
      { name: "Felswurf", beschreibung: "Fernkampfwaffenangriff: +15 auf Treffer, Reichweite 36/144 m, ein Ziel. Treffer: 27 (3W12+8) Wuchtschaden." },
      { name: "Einatmen (Aufladung 5–6)", beschreibung: "Der Nachkomme atmet einen Luftwirbel in einer 36 Meter langen, 4,5 Meter breiten Linie ein. Jede Kreatur in diesem Bereich, die höchstens riesig ist, muss einen SG-23-Stärkerettungswurf bestehen, oder wird sie 36 Meter in gerader Linie zum Nachkommen gezogen und verschluckt. Eine verschluckte Kreatur ist festgesetzt, hat vollständige Deckung gegen Angriffe sowie andere Effekte von außerhalb des Nachkommen und erleidet zu Beginn jedes Zugs des Nachkommen 24 (7W6) Energieschaden. In den Bauch des Nachkommen passen bis zu zwei Kreaturen auf einmal. Wenn der Nachkomme in einem einzigen Zug mindestens 60 Schaden durch eine verschluckte Kreatur erleidet, muss er am Ende des Zugs einen SG-17-Konstitutionsrettungswurf bestehen, oder er würgt alle verschluckten Kreaturen wieder hoch. Diese befinden sich dann im Bereich von bis zu drei Metern um den Nachkommen und sind liegend. Wenn der Nachkomme stirbt, sind die verschluckten Kreaturen nicht mehr festgesetzt und können aus der Leiche entkommen. Sie verwenden dazu 4,5 Meter ihrer Bewegungsrate und sind dann liegend." }
    ],
    bonusaktionen: [
      { name: "Erderschütternde Bewegung", beschreibung: "Der Nachkomme bewegt sich bis zu seiner Bewegungsrate und entfesselt dabei eine Schockwelle in einem auf sich zentrierten Kreis mit einem Radius von 18 Metern, die durch den Boden läuft. Jede Kreatur auf dem Boden, durch den die Schockwelle verläuft, und die Konzentration aufrecht erhält, muss einen SG-23-Konstitutionsrettungswurf bestehen, oder sie verliert ihre Konzentration." }
    ],
    reaktionen: [
      { name: "Nähren", beschreibung: "Unmittelbar nachdem er Schaden erlitten und mindestens eine Kreatur verschluckt hat, fügt der Nachkomme jeder verschluckten Kreatur 10 (3W6) Energieschaden zu und erhält 10 Trefferpunkte zurück." }
    ],
