      { name: "Begräbnisgriff (Wiederaufladung 6)", beschreibung: "Der Nachkomme hüllt seine Hand in versteinernde Magie und berührt eine Kreatur im Abstand von bis zu sechs Metern von sich, die er sehen kann. Das Ziel muss einen SG-24-Geschicklichkeitsrettungswurf bestehen, oder es erleidet 28 (8W6) Energieschaden und wird gepackt (Rettungswurf-SG 19). Wenn das Ziel zu Beginn des nächsten Zugs des Nachkommen immer noch gepackt ist, versteinert es." }
