    zustandsimmunitaeten: ["Bezaubert", "Erschöpft", "Gelähmt", "Liegend", "Verängstigt", "Versteinert"],
    sinne: ["Wahrer Blick 36 m"],
    passiveWahrnehmung: 27,
    sprachen: ["Riesisch", "Urtümlich"],
    umgebung: ["Ozean"],
    bild: "assets/images/monster/ruhm-der-riesen/nachkomme_von_stronmaus.png",
    beschreibung: [
      "Riesen stammen vom Allvater Annam und dessen Kindern ab. Doch Nachkommen der riesischen Götter protzen mit einem gewichtigeren Anspruch: Sie sind Annams Enkel und nehmen dadurch einen privilegierten Platz unter den Riesen ein. Auf einigen Welten herrschten diese Nachkommen über die ersten riesischen Reiche, bis sich Annam in die Abgeschiedenheit zurückzog. Auf anderen Welten bewachen die Nachkommen ihre Geburtsstätten, die reich an elementarer Magie sind, oder halten die Substanz der Welt zusammen.",
      "Nachkommen der riesischen Götter sind ungeheuer mächtige Wesen, die die Welt um sich herum mit urtümlicher Magie erfüllen. Sie schlummern in vielen Welten und sind dort Teil der Landschaft geworden. In solch einem Fall liegt der Nachkomme in Stase und wird von einem mächtigen Elementar umhüllt, den man eine Wiege nennt. Die Wiege schützt den schlummernden Nachkommen und folgt seinen unterbewussten Wünschen, einschließlich der Vertreibung von Eindringlingen. Doch falls die Wiege stirbt, erwacht der Nachkomme darin ganz.",
      "Ein Nachkomme von Stronmaus schlummert oft hoch am Himmel oder tief im Ozean, wo der Tumult, den der unruhige Schlaf des Nachkommen verursacht, wenig Einfluss auf die Welt hat. Kommt er dem Boden oder der Meeresoberfläche zu nahe, verursacht er gewaltige Stürme oder schwere Strudel. Der Schlaf eines Nachkommen ist voller Träume, in denen sich inspirierende Visionen von Annams Rückkehr mit melancholischen Prophezeiungen über einen unvermeidlichen Niedergang ablösen. Freudige Einblicke in eine idyllische Vergangenheit folgen auf schreckliche Albträume voller Qual und Verwüstung.",
      "Die Wiege des Sturmnachkommen handelt nicht nur, wenn der Nachkomme bedroht wird, sondern auch dann, wenn Albträume seinen Schlaf stören. Wird die Wiege geweckt, nimmt sie eine vage riesenförmige Gestalt an, die aus Luft, Wasser und Eis besteht, die wütend umherwirbeln.",
      "Wird die Wiege vernichtet, erwacht der Nachkomme von Stronmaus in ihr. Der Nachkomme zählt zu den mächtigsten Kreaturen unter allen Riesen und ist gewaltige 24 Meter groß. Oft empfindet er das Erwachen als Erleichterung und Befreiung von seinen verstörenden Träumen, weshalb er auch nicht sofort zur Gewalt greift, wenn er aus seiner Wiege auftaucht. Er hat allerdings auch kein besonderes Interesse an Humanoiden oder anderen kleinen Kreaturen – weder um sich mit ihnen zu unterhalten, noch um sie vor Schaden zu schützen, den er anrichten könnte. Wird der Nachkomme bedroht, entfesselt er elementare Kräfte, wie kaum eine andere Macht im Multiversum sie aufbringen kann: zuckende Blitze, felsengroße Hagelkörner und einen Sturm brodelnder Elemente."
    ],
    besonderheiten: [
      { name: "Belagerungsmonster", beschreibung: "Der Nachkomme fügt Gegenständen und Gebäuden den doppelten Schaden zu." },
      { name: "Legendäre Resistenz (6/Tag)", beschreibung: "Wenn sein Rettungswurf scheitert, kann der Nachkomme den Wurf in einen Erfolg verwandeln." },
      { name: "Magieresistenz", beschreibung: "Der Nachkomme ist bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil." },
      { name: "Vorbeifliegen", beschreibung: "Der Nachkomme provoziert keine Gelegenheitsangriffe, wenn er die Reichweite eines Feinds verlässt." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Nachkomme führt einen Blitzschwert- oder Hagelkorn-Angriff sowie zwei Hiebangriffe aus." },
      { name: "Blitzschwert", beschreibung: "Nahkampfwaffenangriff: +18 auf Treffer, Reichweite 9 m, ein Ziel. Treffer: 36 (4W12+10) Energieschaden plus 22 (4W10) Blitzschaden." },
      { name: "Hagelkorn", beschreibung: "Fernkampfwaffenangriff: +18 auf Treffer, Reichweite 36/144 m, ein Ziel. Treffer: 32 (4W10+10) Wuchtschaden plus 18 (4W8) Kälteschaden, und das Ziel muss einen SG-26-Stärkerettungswurf bestehen, oder es wird umgestoßen." },
      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +18 auf Treffer, Reichweite 6 m, ein Ziel. Treffer: 36 (4W12+10) Energieschaden." }
    ],
    bonusaktionen: [
      { name: "Rachsüchtiger Sturm (Aufladung 6)", beschreibung: "Der Nachkomme beschwört eine brodelnde Sturmwolke an einem Punkt im Abstand von bis zu 36 Metern von sich, die einen Zylinder mit einem Radius von sechs Metern und einer Höhe von drei Metern bildet. Der Bereich der Wolke ist komplett verschleiert. Die Wolke hält eine Minute lang an, es sei denn, der Nachkomme stirbt oder verwendet diese Bonusaktion erneut. Wenn die Wolke erscheint – und als Bonusaktion in späteren Runden –, kann der Nachkomme sie bis zu neun Meter weit bewegen und einen der folgenden Effekte in einem 36 Meter hohen Zylinder mit einem Radius von neun Metern direkt unter der Wolke verursachen. Der Nachkomme kann nicht zwei Runden hintereinander denselben Effekt wählen. Blitze: Blitze zucken herab. Jede Kreatur im Zylinder muss einen SG-25-Geschicklichkeitsrettungswurf bestehen, oder sie erleidet 18 (4W8) Blitzschaden und ist bis zum Ende ihres nächsten Zugs betäubt. Froststurm: Eissplitter prasseln herab und eisiger Wind erfüllt den Bereich. Jede Kreatur im Zylinder muss einen SG-25-Geschicklichkeitsrettungswurf bestehen, oder sie erleidet 28 (8W6) Kälteschaden und wird eine Minute lang von Eisformationen festgesetzt – oder bis sie oder eine andere Kreatur in ihrer Reichweite eine Aktion zum Befreien verwendet. Die Bewegungsrate einer vom Eis festgesetzten Kreatur ist auf 0 verringert. Säureregen: Aus der Wolke regnet Säure. Jede Kreatur im Zylinder muss einen SG-25-Konstitutionsrettungswurf bestehen, oder sie ist eine Minute lang mit Säure bedeckt. Kreaturen können als Aktion die Säure von sich oder einer anderen Kreatur entfernen. Mit Säure bedeckte Kreaturen nehmen zu Beginn jedes ihrer Züge 26 (4W12) Säureschaden." }
    ],
    reaktionen: [],
    legendaere_aktionen: null,
    regionale_effekte: {
      beschreibung: "Die Gegend um einen Nachkommen von Stronmaus wird von riesischer Magie beeinflusst, was mindestens einen der folgenden Effekte erzeugt:",
      effekte: [
        "Elementarportale: Im Abstand von bis zu 1,6 Kilometern von der Wiege oder vom Nachkommen bilden sich in beide Richtungen nutzbare Portale zur Elementarebene der Luft (falls sich der Nachkomme am Himmel befindet) oder zur Elementarebene des Wassers (falls sich der Nachkomme im Meer befindet) und ermöglichen elementaren Kreaturen den Eintritt in die Welt.",
        "Extremes Wetter: Das Wetter im Abstand von bis zu 1,6 Kilometern vom Nachkommen ändert sich von Tag zu Tag dramatisch und reicht von angenehm sonnig bis hin zu heftigsten Hagelstürmen.",
        "Verstärkte Sturmriesen: Sturmriesen im Abstand von bis zu 300 Metern vom Nachkommen erhalten einen Bonus von +8 auf Angriffs- und Schadenswürfe. Falls der Nachkomme stirbt, enden diese Effekte sofort."
      ]
    },
    source: "Ruhm der Riesen"
