      { name: "Gletscherumbruch (Aufladung 5–6)", beschreibung: "Der Nachkomme vergräbt die Hände in einem Punkt im Abstand von bis zu neun Metern von sich in den Boden, den er sehen kann, und schleudert eine magisch beschworene Eismasse in die Luft. Jede Kreatur in einem 30 Meter hohen Zylinder mit einem Radius von neun Metern um diesen Punkt muss einen SG-25-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 36 (8W8) Wuchtschaden plus 19 (3W12) Kälteschaden und wird senkrecht zur Oberseite des Zylinders geschoben, um im Anschluss von dort herabzufallen. Bei einem erfolgreichen Rettungswurf erleidet die jeweilige Kreatur halb so viel Schaden und wird ohne weitere Effekte auf die nächste freie Stelle außerhalb des Zylinders geschoben. Zu Beginn der nächsten Runde des Nachkommen stürzt eine Eismasse an einem Punkt auf den Boden, den er sehen kann und der sich im Abstand von bis zu 18 Metern von jenem Punkt befindet, in den der Nachkomme die Hände vergraben hat. Jede Kreatur in einem 30 Meter hohen Zylinder mit einem Radius von neun Metern muss einen SG-25-Geschicklichkeitsrettungswurf bestehen, oder sie erleidet 18 (4W8) Wuchtschaden plus 18 (4W8) Kälteschaden." }
