    verwundbarkeiten: [],
    zustandsimmunitaeten: ["Erschöpft", "Festgesetzt", "Gelähmt", "Vergiftet"],
    sinne: [],
    passiveWahrnehmung: 14,
    sprachen: ["Aural", "Riesisch"],
    umgebung: ["Andere Ebenen"],
    bild: "assets/images/monster/ruhm-der-riesen/nebelkoloss.png",
    beschreibung: [
      "Nebelkolosse stammen von uralten Wolkenriesen ab und sind Elementare, die die vermischte elementare Natur aus Luft und Wasser ihrer Vorfahren verkörpern. Nach zahllosen Jahrhunderten der Isolation – oft auf einer der Elementarebenen oder einer versteckten Halbebene – haben sie bis auf den allerfeinsten Hauch die körperliche Gestalt ihrer Ahnen abgestreift und sich dabei sogar noch weniger von der riesischen Kultur bewahrt.",
      "Ein Nebelkoloss ähnelt einer zweibeinigen Gestalt aus dunklen Regenwolken. Teile seines Körpers scheinen fester zu sein als andere, doch selbst diese sind derart durchscheinend, dass man die aufgewühlten Dämpfe sehen kann, aus denen das Innere des Kolosses besteht. Ständig entweichen Wolkenfetzen aus der Kreatur, als könnte sie sich jederzeit vollständig auflösen. Wird sie getötet, kondensiert ihre neblige Gestalt zu einem Wasserstrom.",
      "Die Stimmung eines Nebelkolosses ist stets düster, und wenn er bedroht wird, heult er oft in ansteckendem Elend auf. Wer dieses Heulen hört, wird auf magische Weise an etwas aus der Vergangenheit erinnert, was er bereut, ob nun berechtigterweise oder nur der eigenen Wahrnehmung wegen."
    ],
    besonderheiten: [
      { name: "Luftgestalt", beschreibung: "Der Nebelkoloss kann in den Bereich einer anderen Kreatur eindringen und dort stoppen. Er kann sich durch einen engen Bereich mit einer Breite von nur 2,5 Zentimetern bewegen, ohne sich quetschen zu müssen." },
      { name: "Todesexplosion", beschreibung: "Stirbt der Nebelkoloss, zerplatzt er in einer Wasserwelle. Jede Kreatur im Abstand von bis zu drei Metern muss einen SG-16-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 11 (2W10) Wuchtschaden und wird umgestoßen. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Nebelkoloss führt zwei Hiebangriffe aus." },
      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +8 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 16 (2W10+5) Kälteschaden." },
      { name: "Schreckliches Geheul (Aufladung 5–6)", beschreibung: "Der Nebelkoloss entfesselt ein Heulen, das von magischer Qual durchdrungen ist. Jede Kreatur im Abstand von bis zu neun Metern muss einen SG-14-Weisheitsrettungswurf bestehen. Eine Kreatur im Bereich des Nebelkolosses ist bei diesem Rettungswurf im Nachteil. Scheitert der Wurf, erleidet die Kreatur 14 (4W6) psychischen Schaden und ist eine Minute lang kampfunfähig. Die betroffene Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und den Effekt bei einem Erfolg beenden." }
    ],
    bonusaktionen: [],
