      { name: "Mehrfachangriff", beschreibung: "Der Regisaurus führt einen Biss- und einen Schwanzangriff aus. Er kann nicht beide Angriffe gegen dasselbe Ziel ausführen." },
      { name: "Biss", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 47 (6W12+8) Stichschaden, und das Ziel wird gepackt (Rettungswurf-SG 18). Solange das Ziel gepackt bleibt, ist es festgesetzt. Der Regisaurus kann solange kein weiteres Ziel beißen." },
      { name: "Schwanz", beschreibung: "Nahkampfwaffenangriff: +13 auf Treffer, Reichweite 6 m, ein Ziel. Treffer: 26 (4W8+8) Wuchtschaden." }
