    beschreibung: [
      "Riesenluchse werden zwar oft für normale Katzen gehalten, doch sie sind magische Kreaturen und stammen aus den verschneiten Wäldern des Feywild. Ihr Fell wird im Winter heller, sodass sie sich in ihrer Lieblingsumgebung auch dann verstecken können, wenn diese verschneit ist. Sie sind fähige Jäger, die bisweilen in kleinen Gruppen kooperieren, um Beute in die Falle zu locken, und gelegentlich eine magische Gabe verwenden, um vielversprechende Beuteplätze auszukundschaften. Außerdem sind sie klug genug, um die Jäger zu überlisten, die ihnen nach dem Fell trachten. Besonders gerne entschärfen sie Fallen, die sie in ihren Territorien finden.",
      "Frost- und Wolkenriesen freunden sich manchmal mit Riesenluchsen an und behandeln sie als geschätzte Haustiere. Die Luchse teilen gerne ihre Erkenntnismagie mit den riesischen Gefährten, solange diese ihre Intelligenz und ihre Unabhängigkeit respektieren."
    ],
