      "Riesenwidder sind sehr beliebte Nutztiere bei den Riesen. Das Vlies der Widder speichert magische Energie, indem es sie aus der Umgebung aufnimmt und Kraft aus Zaubersprüchen zieht. Solange ein Widder am Leben und ungeschoren ist, nutzt er die Magie seines Vlieses zur Selbstverteidigung. Er bündelt die Energie, die er damit absorbiert, zu einer magischen Explosion, um so Raubtiere zu vertreiben.",
