      { name: "Stampfen", beschreibung: "Nahkampfwaffenangriff: +14 auf Treffer, Reichweite 6 m, ein Ziel. Treffer: 29 (4W10+7) Wuchtschaden. Wenn das Ziel eine höchstens riesige Kreatur ist, muss es einen SG-22-Geschicklichkeitsrettungswurf bestehen, oder es wird umgestoßen. Bis der Koloss sein Stampfen erneut einsetzt oder sich bewegt, ist die Kreatur festgesetzt. Die festgesetzte Kreatur oder eine andere Kreatur im Abstand von bis zu 1,5 Metern von ihr kann ihre Aktion verwenden, um einen SG-22-Stärkewurf auszuführen. Bei einem Erfolg wird die Kreatur an eine freie Stelle ihrer Wahl im Abstand von bis zu 1,5 Metern zum Koloss bewegt und ist nicht mehr festgesetzt." },
      { name: "Arkanstrahl (Aufladung 5–6)", beschreibung: "Der Koloss feuert einen Strahl aus magischer Energie aus Brust, Händen oder Kopf in einer 45 Meter langen und drei Meter breiten Linie ab. Jede Kreatur in diesem Bereich muss einen SG-22-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 58 (9W12) Energieschaden, anderenfalls die Hälfte." }
