      { name: "Biss", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 19 (2W12+6) Stichschaden." },
      { name: "Reißzahnschleudern", beschreibung: "Fernkampfwaffenangriff: +10 auf Treffer, Reichweite 9/27 m, ein Ziel. Treffer: 11 (1W10+6) Stichschaden." },
      { name: "Schlingender Ansturm (Aufladung 5–6)", beschreibung: "Der Schlund nutzt seine Bewegungsrate, ohne Gelegenheitsangriffe zu provozieren, und kann sich durch den Bereich großer oder kleinerer Kreaturen bewegen. Jedes Mal, wenn der Schlund während seiner Bewegung zum ersten Mal den Bereich einer Kreatur betritt, muss die betroffene Kreatur einen SG-18-Stärkerettungswurf bestehen, oder sie erleidet 25 (3W12+6) Stichschaden und wird gepackt (Rettungswurf-SG 16). Wenn der Schlund bereits eine Kreatur auf diese Weise gepackt hat, wird die nächste Kreatur umgestoßen. Solange das Ziel gepackt bleibt, ist es festgesetzt. Der Schlund kann so nur jeweils eine Kreatur packen." }
