      { name: "Hieb", beschreibung: "Nahkampfwaffenangriff: +7 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 13 (2W8+4) Wuchtschaden." },
      { name: "Stechender Staub", beschreibung: "Eine Kreatur nach Wahl des Staubkolosses innerhalb seiner Reichweite muss einen SG-14-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 10 (3W6) Wuchtschaden und ist bis zum Ende ihres nächsten Zugs blind. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden." }
