    bild: "assets/images/monster/ruhm-der-riesen/steinhuegelschrecken.png",
    beschreibung: [
      "Steinriesen glauben, dass der Gott Skoraeus Steinknochen Künstler zu ihren feinsten Steinmetzarbeiten inspiriert. Manche Riesen gehen dieser göttlichen Inspiration so radikal nach, dass sie alle anderen Aufgaben vernachlässigen, sich in geräumige Höhlen zurückziehen und alle Ablenkungen von sich fernhalten. Das Schaffen eines Meisterwerks kann eine solche Obsession werden, dass noch nicht mal der Tod das Ende bedeutet: Ein Riese, der beim künstlerischen Schaffen stirbt, kann sich als Steinhügelschrecken erheben und seine Arbeit fortsetzen. Ist das Werk vollbracht, so bleibt der Steinhügelschrecken als unsterblicher Wächter bei ihm.",
      "Ein Steinhügelschrecken sieht aus wie ein ausgezehrter Steinriese. Seine Gestalt ist von Flechten und Mineralablagerungen übersät, was ihn optisch mit seinem Höhlengrab verschmelzen lässt. Wenn eine Kreatur versucht, die Vollendung des Werks des Steinhügelschrecken zu stören, dem Kunstwerk Schaden zuzufügen oder den Steinhügelschrecken zu bestehlen, lässt dieser die Kreatur versteinern, platziert sie draußen als Warnung und versiegelt dann sein Höhlengrab."
    ],
