      { name: "Versteinernde Berührung (Aufladung 5–6)", beschreibung: "Der Steinhügelschrecken berührt eine Kreatur im Abstand von bis zu drei Metern von sich, die er sehen kann. Das Ziel muss einen SG-17-Konstitutionsrettungswurf bestehen, oder es erleidet 26 (4W12) Energieschaden und ist festgesetzt, da es zu versteinern beginnt. Das betroffene Ziel muss den Rettungswurf am Ende seines nächsten Zugs wiederholen. Bei einem erfolgreichen Rettungswurf endet der Effekt auf das Ziel. Scheitert der Wurf, so ist das Ziel nicht mehr festgesetzt, sondern versteinert." }
