      { name: "Todesblitz (Aufladung 5–6)", beschreibung: "Der Geist schleudert einen magischen Blitz in einer 36 Meter langen, drei Meter breiten Linie. Jede Kreatur in diesem Bereich muss einen SG-18-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 27 (6W8) Blitzschaden plus 16 (3W10) nekrotischen Schaden, anderenfalls die Hälfte. Unabhängig vom Ergebnis ist das Trefferpunktemaximum der betroffenen Kreatur um den Betrag des erlittenen nekrotischen Schadens verringert. Es bleibt verringert, bis die Kreatur eine lange Rast beendet. Wird das Trefferpunktemaximum auf 0 verringert, stirbt die Kreatur." }
