    bild: "assets/images/monster/ruhm-der-riesen/sturmkrabbe.png",
    beschreibung: [
      "Sturmkrabben sind kolossale Krebstiere mit vier monströsen Scheren und einem giftigen Stachel. Sie fühlen sich unter Wasser ebenso wohl wie an Land und können einen unter hohem Druck stehenden Wasserstrahl abgeben, der Feinde einfach zermalmt.",
      "Die Riesen mancher Welten behaupten, Stronmaus oder eines seiner Kinder habe Sturmkrabben in den Anfangsjahren eines Reichs aus alten Zeiten erschaffen. So wie Behire erschaffen wurden, um Drachen an Land zu bekämpfen, und Rache, um die Drachen am Himmel herauszufordern, sollten Sturmkrabben gegen Drachenschildkröten, Bronzedrachen und andere Feinde im Wasser antreten. Auf vielen Welten hüten diese Kreaturen eifersüchtig die Unterseefestungen der Sturmriesen sowie jene verwüsteten Bastionen, die schon lange von den Riesen aufgegeben worden sind."
    ],
    besonderheiten: [
      { name: "Amphibisch", beschreibung: "Die Krabbe kann Luft und Wasser atmen." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Die Krabbe führt zwei Scherenangriffe und einen Stachelangriff aus." },
      { name: "Schere", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 4,5 m, ein Ziel. Treffer: 19 (3W8+6) Wuchtschaden. Wenn das Ziel eine höchstens riesige Kreatur ist, wird es gepackt (Rettungswurf-SG 16). Die Krabbe hat vier Scheren, von denen jede jeweils ein Ziel packen kann." },
      { name: "Stachel", beschreibung: "Nahkampfwaffenangriff: +10 auf Treffer, Reichweite 3 m, eine Kreatur. Treffer: 22 (3W10+6) Stichschaden, und das Ziel muss einen SG-17-Konstitutionsrettungswurf bestehen, oder es ist eine Minute lang vergiftet und gelähmt. Die betroffene Kreatur kann den Rettungswurf am Ende jedes ihrer Züge wiederholen und die beide Effekte bei einem Erfolg beenden." },
      { name: "Wasserstrahl (Aufladung 5–6)", beschreibung: "Die Krabbe atmet einen Wasserstrahl in einer 45 Meter langen, drei Meter breiten Linie aus. Jede Kreatur in diesem Bereich muss einen SG-17-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 27 (6W8) Wuchtschaden und wird bis zu neun Meter weit von der Krabbe weg- und umgestoßen. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden." }
    ],
