    bild: "assets/images/monster/ruhm-der-riesen/sturmriesen-sturmrufer.png",
    beschreibung: [
      "Während die meisten Sturmriesen sich wenig um die komplizierten Einzelheiten der Rangabfolge innerhalb des Ordnings scheren, beanspruchen Sturmrufer stolz eine Position an der Spitze dieser Rangliste – und nur wenige wagen es, sie herauszufordern. Diese Sturmriesen gebieten neben der angeborenen, sie durchströmenden Magie über die Macht der Runenmagie, was ihnen großen Respekt einbringt. Wenn ein Riese Annams Aufmerksamkeit je wieder auf die Welt lenken kann, wird es wahrscheinlich ein Sturmrufer sein.",
      "Sturmrufer pflanzen sich Kristallkugeln mit eingravierten Sturmrunen in die Stirn oder in die Augenhöhlen ein, um magische Täuschungen durchschauen zu können. Sie können auch einen zeitweiligen Strudel aus eisigen Winden und Sturmwolken um sich herum erzeugen, die ihre Feinde in elementare Wut einhüllen."
    ],
    besonderheiten: [
      { name: "Amphibisch", beschreibung: "Der Riese kann Luft und Wasser atmen." },
      { name: "Ausspähung (erfordert Sturmrune)", beschreibung: "Der Riese kann seine Kristallkugel verwenden, um den Zauber Ausspähung zu wirken (Rettungswurf-SG 17)." },
      { name: "Legendäre Resistenz (3-mal täglich)", beschreibung: "Wenn sein Rettungswurf scheitert, kann der Riese den Wurf in einen Erfolg verwandeln." },
      { name: "Sturmrune", beschreibung: "Der Riese besitzt eine Sturmrune, die in eine Kristallkugel eingraviert wurde. Solange der Riese den Gegenstand mit der Rune in seinem Körper trägt, kann er dessen Sturmruf-Aktion und dessen Merkmal Ausspähung verwenden. Der Gegenstand mit der Sturmrune besitzt eine RK von 17, 50 Trefferpunkte und ist gegen Gift-, nekrotischen und psychischen Schaden immun. Er erhält am Ende jedes Zugs alle Trefferpunkte zurück, zerfällt jedoch zu Staub, wenn seine Trefferpunkte auf 0 sinken oder der Riese stirbt. Wenn die Rune zerstört wird, kann der Riese nach einer kurzen oder langen Rast eine Sturmrune in eine andere Kristallkugel in seinem Besitz gravieren." },
      { name: "Wachsam", beschreibung: "Der Riese kann nicht überrascht werden und ist bei Initiativewürfen im Vorteil." }
    ],
    aktionen: [
      { name: "Mehrfachangriff", beschreibung: "Der Riese führt drei Blitzklinge- oder Blitzlanze-Angriffe aus." },
      { name: "Blitzklinge", beschreibung: "Nahkampfwaffenangriff: +15 auf Treffer, Reichweite 3 m, ein Ziel. Treffer: 22 (3W8+9) Hiebschaden plus 16 (3W10) Blitzschaden." },
      { name: "Blitzlanze", beschreibung: "Fernkampf-Zauberangriff: +13 auf Treffer, Reichweite 150 m, ein Ziel. Treffer: 39 (5W12+7) Blitzschaden." },
      { name: "Sturmruf (erfordert Sturmrune)", beschreibung: "Der Riese erzeugt einen elementaren Wirbel, der eine Kugel mit einem Radius von 18 Metern füllt und auf ihn selbst zentriert ist. Jede Kreatur in diesem Bereich (außer dem Riesen) muss einen SG-21-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 43 (8W8+7) Schaden nach Wahl des Riesen: Blitz, Kälte oder Schall. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur halb so viel Schaden." },
      { name: "Zauberwirken", beschreibung: "Der Riese wirkt einen der folgenden Zauber, benötigt dazu keine Materialkomponenten und verwendet Charisma als Attribut zum Zauberwirken (Zauberrettungswurf-SG 21, +13 auf Treffer mit Zauberangriffen): Beliebig oft: Gedanken wahrnehmen, Magie entdecken. 1-mal täglich: Ebenenwechsel, Magie bannen, Verständigung, Wasser kontrollieren, Wetterkontrolle (als Aktion), Zeitstopp." }
    ],
