    beschreibung: [
      "Vor langer Zeit reiste eine große Bande von Wolkenriesen ins Schattenfell – auf der Suche nach einer Möglichkeit, ihr zusammenbrechendes Imperium zu retten. In ihrer verzweifelten Bemühung, sich selbst und ihre Lebensweise zu retten, schlossen sie eine Wette mit der Rabenkönigin ab, jener mysteriösen Göttin des Todes und der Erinnerung, die auf der Ebene existiert. Es gibt verschiedene Geschichten der Wette und ihres Ergebnisses: Manchen zufolge löste die Rabenkönigin jedes Rätsel, das die Riesen ihr stellten, bis die Riesen irgendwann erschöpft zusammenbrachen. Andere beschreiben eine Reihe von zunehmend unwahrscheinlichen Ereignissen, die der Rabenkönigin bei jeder Wette in die Hände spielten. Sicher ist, dass die Riesen die Rabenkönigin ernstlich unterschätzt hatten. Als sie endgültig verloren hatten, wurde das Schattenfell ihre Heimat, und seither dienen sie zähneknirschend der Rabenkönigin.",
      "Im Laufe der Zeit verwandelte das Schattenfell diese Riesen. Ihre Leiber schrumpften, und ihre Gesichter nahmen ein tiefes Lila an. Sie wurden zu den ersten Todesriesen, und ihre Nachfahren spuken noch heute im Schattenfell und suchen sowohl dort als auch auf der materiellen Ebene nach Seelen, die ihrer göttlichen Königin gefallen könnten.",
      "Todesriesen-Schnitter führen massive Sensen und tragen Rüstungen, die dem Panzer von Rieseninsekten ähneln. Sie gebieten über die Magie der Schatten, die sie grausig aussehen lässt und mit der Fähigkeit zu verschwinden ausstattet. Außerdem können sie Schatten in grauenhaften Energieschlägen bündeln, die ihren Opfern die Lebensenergie rauben."
    ],
