      { name: "Seelenblitz", beschreibung: "Fernkampf-Zauberangriff: +8 auf Treffer, Reichweite 36 m, eine Kreatur. Treffer: 26 (4W10+4) nekrotischer Schaden. Wenn das Ziel verängstigt ist, erhält der Riese temporäre Trefferpunkte in Höhe des bewirkten Schadens." }
