      { name: "Zauberwirken", beschreibung: "Der Riese wirkt einen der folgenden Zauber und verwendet Intelligenz als Attribut zum Zauberwirken: Beliebig oft: Magierrüstung, Magie entdecken. 3-mal täglich: Mit Toten sprechen, Tensers Schwebende Scheibe." }
