      { name: "Seelenhülle (erfordert Todesrune)", beschreibung: "Der Riese hüllt sich in einen Seelenstrom. Solange er verhüllt ist, muss jede Kreatur, die ihren Zug im Abstand von bis zu 1,5 Metern vom Riesen beginnt, einen SG-19-Weisheitsrettungswurf bestehen, oder sie ist bis zum Ende ihres nächsten Zugs bei Rettungswürfen im Nachteil. Die Hülle verschwindet nach einer Minute, wenn der Riese stirbt, diese Bonusaktion erneut einsetzt oder seine Todesrune zerstört wird." }
