      { name: "Legendäre Resistenz (5/Tag)", beschreibung: "Scheitert ein Rettungswurf der Wiege, kann sie den Wurf in einen Erfolg verwandeln." },
      { name: "Magieresistenz", beschreibung: "Die Wiege ist bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil." },
      { name: "Vorbeifliegen", beschreibung: "Die Wiege provoziert keine Gelegenheitsangriffe, wenn sie die Reichweite eines Feinds verlässt." }
