      { name: "Zunderwoge (Aufladung 5–6)", beschreibung: "Der Zunderkoloss stößt aus seinem Gesicht, seinen Händen oder seiner Brust eine Woge aus schwelender Asche in einem Kegel von neun Metern aus. Jede Kreatur in diesem Bereich muss einen SG-16-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 31 (7W8) Feuerschaden und ist bis zum Ende ihres nächsten Zugs blind. Bei einem erfolgreichen Rettungswurf erleidet die Kreatur nur halb so viel Schaden." }
